import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Fragment,
	Host,
	Method,
	Prop,
	State,
	h,
} from "@stencil/core";
import {
	caretDown,
	indicatorComplete,
	indicatorDefault,
	indicatorError,
	indicatorInactive,
	indicatorProgress,
} from "../../../icons/index";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
/**
 * @since 1.1.20
 * @status dev
 *
 * @data-testid activityTimeline-rightarrow - The default expand or collapse trigger control.
 * @data-testid activityTimeline-label - The panel label element.
 *
 * @slot - The panel' content.
 * @slot header - The panel's header. Alternatively, you can use the label and subtext prop.
 * @slot trigger - The expand/collapse trigger icon.
 * @slot icon - The icon status for the activity timeline.
 *
 * @part base - The component's base wrapper.
 * @part header - The label header.
 * @part label - The panel's label.
 * @part subtext - The panel's subtitle.
 * @part trigger - The expand/collapse trigger icon.
 * @part content - The timeline panel's content.
 */

@Component({
	tag: "hbr-timeline-panel",
	styleUrl: "activity-timeline-panel.scss",
	shadow: true,
})
export class TimelinePanel {
	isVisible = false;
	/**
	 *
	 * The label to show in the activity timeline header. If you need to display HTML, use the `header` slot instead.
	 */
	@Prop() label: string;

	/**
	 * Subtitle of the activity timeline header.
	 */
	@Prop() subtext = "";

	/**
	 * Indicates whether or not the activity panel is open
	 */
	@Prop({ mutable: true, reflect: true }) open = false;

	/**
	 * variant of the panel. Possible values are default, progress, error, complete and inactive
	 */
	@Prop({ reflect: true }) variant:
		| "default"
		| "progress"
		| "complete"
		| "error"
		| "inactive" = "default";

	@Prop() progress: number | null = null; // not available

	/**
	 * Make the activity timeline panel collapsible to display additional content
	 */
	@Prop() collapsible = false;

	/** Attributes related to screen readers. */
	@Prop() aria: { level?: number };

	@State() uuid: boolean;

	@Element() private el: HTMLHbrTimelinePanelElement;

	/** Emitted when the activity panel opens. Calling `event.preventDefault()` will prevent it from being opened. */
	@Event({ eventName: "hbr-show" }) hbrShow: EventEmitter;

	/** Emitted after the activity opens and all transitions are complete. */
	@Event({ eventName: "hbr-after-show" }) hbrAfterShow: EventEmitter;

	/** Emitted when the activity closes. Calling `event.preventDefault()` will prevent it from being closed. */
	@Event({ eventName: "hbr-hide" }) hbrHide: EventEmitter;

	/** Emitted after the activity closes and all transitions are complete. */
	@Event({ eventName: "hbr-after-hide" }) hbrAfterHide: EventEmitter;

	componentDidLoad() {
		if (this.collapsible) {
			this.el.setAttribute("tabIndex", "0");
			this.el.addEventListener("keydown", this.handleKeyDown.bind(this));
		}
	}

	handleKeyDown = (event) => {
		if (
			event &&
			event.type === "keydown" &&
			event.code !== "Enter" &&
			event.code !== "Space"
		)
			return;
		this.handleClick();
	};

	@Method()
	async show() {
		// Prevent subsequent calls to the method, whether manually or triggered by the `open` watcher
		if (this.isVisible) {
			return;
		}

		const hbrShow = this.hbrShow.emit();
		if (hbrShow.defaultPrevented) {
			return;
		}

		this.isVisible = true;
		this.open = !this.open;
		if (this.collapsible) {
			this.el.setAttribute("aria-expanded", `${this.open}`);
		}
	}

	handleClick = () => {
		this.open = !this.open;
		if (this.collapsible) {
			this.el.setAttribute("aria-expanded", `${this.open}`);
		}
	};

	render() {
		let content: JSX.Element | null = null;
		let rightarrow: JSX.Element | undefined;
		let slotcontent: JSX.Element | undefined;
		let iconContent: JSX.Element | undefined;
		let progress: JSX.Element | undefined;

		const customSystemIcons = getBootstrapConfig()?.systemIcons;

		const iconsForVariant = {
			default: customSystemIcons?.["indicator-default"] || indicatorDefault,
			progress: customSystemIcons?.["indicator-progress"] || indicatorProgress,
			complete: customSystemIcons?.["indicator-complete"] || indicatorComplete,
			error: customSystemIcons?.["indicator-error"] || indicatorError,
			inactive: customSystemIcons?.["indicator-inactive"] || indicatorInactive,
		};

		const finalValue =
			this.progress && this.progress >= 100
				? 100
				: this.progress && this.progress < 0
				  ? 0
				  : this.progress;

		const circle =
			this.progress && this.progress > 0 && this.progress !== 100 ? (
				<span class="circle" />
			) : (
				<div />
			);

		if (this.progress !== null && !Number.isNaN(this.progress)) {
			progress = (
				<div
					style={{
						width: "56px",
						position: "relative",
						marginTop: "39px",
						left: "-23px",
					}}
				>
					<div
						class="hbr-progress-container"
						style={{ "-webkit-transform": "rotate(90deg)" }}
					>
						<div class="hbr-progress-meter">
							<span style={{ width: `${finalValue}%` }} />
							{circle}
						</div>
					</div>
				</div>
			);
		}

		if (!this.collapsible) {
			rightarrow = <span />;
			slotcontent = (
				<div
					class={{
						"hbr-activity-timeline-panel-item__inner": true,
						collapsible: this.collapsible,
						"no-collapsible": !this.collapsible,
					}}
					part="content"
					style={{ visibility: this.open ? "visible" : "hidden" }}
					id={`section-${this.uuid}`}
				>
					<slot />
				</div>
			);
		} else {
			rightarrow = (
				<span
					class="hbr-activity-timeline-panel-item__icon"
					onClick={this.handleClick}
					data-testid="activityTimeline-rightarrow"
					part="trigger"
				>
					<slot name="trigger">
						<hbr-icon asset={customSystemIcons?.["caret-down"] || caretDown} />
					</slot>
				</span>
			);

			slotcontent = (
				<div
					part="content"
					class={{
						"hbr-activity-timeline-panel-item__inner": true,
						collapsible: this.collapsible,
						"no-collapsible": !this.collapsible,
					}}
					style={{ visibility: this.open ? "visible" : "hidden" }}
					id={`section-${this.uuid}`}
				>
					<slot />
				</div>
			);
		}

		const titleStyle = this.open
			? "hbr-activity-timeline-panel-item__title open"
			: "hbr-activity-timeline-panel-item__title";
		//const iconStyle = this.variant ? `hbr-activity-timeline_icon_container ${this.variant}` : "hbr-activity-timeline_icon_container"
		const iconBackground =
			this.progress === null
				? "hbr-activity-timeline-panel-item__icon2"
				: this.progress < 0
				  ? "hbr-activity-timeline-panel-item__icon2 negative"
				  : this.progress >= 0
					  ? "hbr-activity-timeline-panel-item__icon2 positive"
					  : "hbr-activity-timeline-panel-item__icon2";

		if (this.progress === null) {
			iconContent = (
				<slot name="icon">
					{this.variant && iconsForVariant[this.variant] ? (
						<hbr-icon
							asset={iconsForVariant[this.variant]}
							class={{
								"hbr-activity-timeline-panel-item-indicator-icon": true,
								[this.variant]: true,
							}}
						/>
					) : null}
				</slot>
			);
		} else {
			iconContent = <div />;
		}
		content = (
			<Fragment>
				<div class="hbr-activity-timeline-panel-item__line">
					<div class={iconBackground}>{iconContent}</div>
					{progress}
					<div
						class={{
							"hbr-activity-timeline-main-header-collapsible":
								this.collapsible && !this.open,
							"hbr-activity-timeline-main-header-collapsible-open":
								this.collapsible && this.open,
						}}
					>
						{rightarrow}
						<slot name="header">
							<div
								part="header"
								class={
									this.progress !== null && !Number.isNaN(this.progress)
										? `hbr-activity-timeline-title_container ${
												this.open ? "open" : ""
										  } ${
												this.collapsible ? "" : "noncollapsible"
										  } hbr-activity-progress`
										: `hbr-activity-timeline-title_container ${
												this.open ? "open" : ""
										  } ${this.collapsible ? "" : "noncollapsible"}`
								}
							>
								<div
									class={titleStyle}
									{...(!this.collapsible ? { "aria-expanded": this.open } : {})}
									data-testid="activityTimeline-label"
									part="label"
									{...(this.aria?.level
										? { role: "heading", "aria-level": this.aria.level }
										: {})}
								>
									{this.label || String.fromCharCode(65279)}
								</div>
								<div
									class="hbr-activity-timeline-panel-item__subtitle"
									part="subtext"
								>
									{this.subtext}
								</div>
							</div>
						</slot>
					</div>
				</div>
				{slotcontent}
			</Fragment>
		);

		return (
			<Host role="listitem">
				<li
					part="base"
					class={`hbr-activity-timeline-panel-list__item ${
						this.open ? "hbr-activity-timeline-panel-list__item--open" : ""
					}`}
					role="presentation"
				>
					<div
						class={`hbr-activity-timeline-panel-item ${
							this.open
								? `hbr-activity-timeline-panel-item--open ${this.variant}`
								: ""
						}`}
					>
						{content}
					</div>
				</li>
			</Host>
		);
	}
}
